begin;
create function pg_temp.assert_stove_type(ok boolean,message text) returns void language plpgsql as $$begin if ok is not true then raise exception 'FAIL: %',message;end if;end $$;
insert into auth.users(id,email,is_anonymous) values('db030000-0000-4000-8000-000000000001','dashboard-stove-types@example.invalid',false);
set local role authenticated;
select set_config('request.jwt.claim.sub','db030000-0000-4000-8000-000000000001',true);
select public.setup_business('Disposable Dashboard stove types','Type owner');
reset role;
do $$declare t uuid:=app_private.current_tenant_id();reg uuid;single_type uuid;custom_type uuid;zero_type uuid;hidden_type uuid;a uuid;b uuid;c uuid;s uuid;cancelled uuid;custom_sale uuid;r jsonb;begin
 r:=public.get_dashboard_snapshot();
 perform pg_temp.assert_stove_type(jsonb_array_length(r->'stove_types')=5,'New business has exactly five default type cards before any product or sale');
 perform pg_temp.assert_stove_type((select jsonb_agg(x->>'name' order by n) from jsonb_array_elements(r->'stove_types') with ordinality v(x,n))='["Single Stove","Double Stove","Regulator","Pipe","Others"]'::jsonb,'Requested default labels and order');
 perform pg_temp.assert_stove_type((select count(distinct x->>'system_key')=5 and sum((x->>'quantity')::integer)=0 from jsonb_array_elements(r->'stove_types')x),'Five dedicated default icon identities and real zero counts');
 select type_id into reg from public.stove_product_types where tenant_id=t and system_key='regulator';
 select type_id into single_type from public.stove_product_types where tenant_id=t and system_key='single_stove';
 a:=(public.save_stove_product(jsonb_build_object('name','Brand A regulator','type_id',reg),gen_random_uuid())->>'item_id')::uuid;
 b:=(public.save_stove_product(jsonb_build_object('name','Brand B regulator','type_id',reg),gen_random_uuid())->>'item_id')::uuid;
 for c in select unnest(array[a,b]) loop
  perform public.adjust_inventory(jsonb_build_object('item_id',c,'kind','opening','filled_quantity',5,'empty_quantity',0,'filled_unit_cost',100,'reason','Explicit stove type test opening'),gen_random_uuid());
  insert into public.price_books(tenant_id,item_id,price_type,customer_tier,price,effective_from) values(t,c,'package','retail',1000,now()-interval '1 day');
 end loop;
 s:=(public.create_pos_sale('01780000931','Stove type buyer',null,null,'retail',0,0,null,jsonb_build_array(jsonb_build_object('item_id',a,'type','package','quantity',2,'unit_price',1000),jsonb_build_object('item_id',b,'type','package','quantity',3,'unit_price',1000)),null,gen_random_uuid(),'[]',null)->>'sale_id')::uuid;
 cancelled:=(public.create_pos_sale('01780000932','Cancelled type buyer',null,null,'retail',0,0,null,jsonb_build_array(jsonb_build_object('item_id',b,'type','package','quantity',1,'unit_price',1000)),null,gen_random_uuid(),'[]',null)->>'sale_id')::uuid;
 perform public.reverse_sale(cancelled,'Cancelled type quantity must not count','CANCEL',gen_random_uuid());
 r:=public.get_dashboard_snapshot();
 perform pg_temp.assert_stove_type((select (x->>'quantity')::integer=5 from jsonb_array_elements(r->'stove_types')x where x->>'type_id'=reg::text),'Two distinct regulator products aggregate to five units; cancelled unit excluded');
 custom_type:=public.save_stove_product_type('Custom fitting');zero_type:=public.save_stove_product_type('No sales custom');hidden_type:=public.save_stove_product_type('Hidden zero');
 perform public.save_stove_product_type('Hidden zero',hidden_type,false);
 c:=(public.save_stove_product(jsonb_build_object('name','Custom fitting SKU','type_id',custom_type),gen_random_uuid())->>'item_id')::uuid;
 perform public.adjust_inventory(jsonb_build_object('item_id',c,'kind','opening','filled_quantity',3,'empty_quantity',0,'filled_unit_cost',50,'reason','Custom type test opening'),gen_random_uuid());
 insert into public.price_books(tenant_id,item_id,price_type,customer_tier,price,effective_from) values(t,c,'package','retail',100,now()-interval '1 day');
 custom_sale:=(public.create_pos_sale('01780000933','Custom type buyer',null,null,'retail',0,0,null,jsonb_build_array(jsonb_build_object('item_id',c,'type','package','quantity',2,'unit_price',100)),null,gen_random_uuid(),'[]',null)->>'sale_id')::uuid;
 r:=public.get_dashboard_snapshot();
 perform pg_temp.assert_stove_type((select (x->>'quantity')::integer=2 and x->'system_key'='null'::jsonb from jsonb_array_elements(r->'stove_types')x where x->>'type_id'=custom_type::text),'Custom type uses generic icon identity and totals its actual sales');
 perform pg_temp.assert_stove_type((select (x->>'quantity')::integer=0 from jsonb_array_elements(r->'stove_types')x where x->>'type_id'=zero_type::text),'New custom type appears before any products or sales');
 perform pg_temp.assert_stove_type(not exists(select 1 from jsonb_array_elements(r->'stove_types')x where x->>'type_id'=hidden_type::text),'Inactive zero-sale type hidden');
 perform public.save_stove_product_type('Renamed single',single_type,true);
 perform public.save_stove_product_type('Regulator',reg,false);
 r:=public.get_dashboard_snapshot();
 perform pg_temp.assert_stove_type((select x->>'system_key'='single_stove' and x->>'name'='Renamed single' from jsonb_array_elements(r->'stove_types')x where x->>'type_id'=single_type::text),'Renaming default retains dedicated icon identity');
 perform pg_temp.assert_stove_type((select (x->>'quantity')::integer=5 from jsonb_array_elements(r->'stove_types')x where x->>'type_id'=reg::text),'Inactive type with sales today remains visible');
 perform public.reverse_sale(s,'Original type sale returned','CANCEL',gen_random_uuid());
 r:=public.get_dashboard_snapshot();perform pg_temp.assert_stove_type(not exists(select 1 from jsonb_array_elements(r->'stove_types')x where x->>'type_id'=reg::text),'Cancellation removes the inactive type once its sold quantity is zero');
 perform pg_temp.assert_stove_type(not has_function_privilege('authenticated','app_private.dashboard_stove_types(uuid)','execute'),'Private aggregate cannot be called with another tenant ID');
end $$;
set constraints all immediate;
select 'PASS: five seeded zero-sale type cards, dedicated identities, cross-product totals, custom/zero/inactive types, renames, cancellation and private tenant scope';
rollback;
